const parsed = $input.first().json?.message?.content
            || $input.first().json?.content
            || $input.first().json;

if (!parsed || parsed.error) {
  return [{ json: { error: parsed?.error || 'No data' } }];
}

const ENTRY = {
  date:              'entry.1576360786',
  shift:             'entry.1608537871',
  group:             'entry.951079054',
  sku:               'entry.1863257644',
  machine:           'entry.1046294258',
  plan_box:          'entry.1956754644',
  actual_box:        'entry.859506834',
  workers:           'entry.657321124',
  actual_pcs:        'entry.803627682',
  run_time:          'entry.659163745',
  counter:           'entry.614687862',
  machine_cycle:     'entry.1629897819',
  setup_time:        'entry.1396861733',
  break_time:        'entry.2050207975',
  clean_time:        'entry.368506841',
  stop_after_target: 'entry.1695251493',
  bdown_time:        'entry.347177147',
  machine_run_time:  'entry.161318891',
  status:            'entry.1662957128',
  miss_reason:       'entry.1473766728',
  warehouse_pcs:     'entry.313587582',
  waste_type:        'entry.898355120',
  waste_pcs:         'entry.56072060',
  damage_reason:     'entry.232574576'
};

const fbzx = String(Math.floor(Math.random() * 9e18));
const now = Date.now();
const parts = [];

parts.push('fvv=1');
parts.push('pageHistory=0');
parts.push('dlut=' + now);
parts.push('fbzx=' + fbzx);
parts.push('submissionTimestamp=' + now);
parts.push('partialResponse=' + encodeURIComponent('[null,null,"' + fbzx + '"]'));

const rawDate = parsed.date;
const d = (rawDate && rawDate !== 'YYYY-MM-DD' && !isNaN(new Date(rawDate)))
          ? new Date(rawDate)
          : new Date();

parts.push(ENTRY.date + '_year=' + d.getFullYear());
parts.push(ENTRY.date + '_month=' + (d.getMonth() + 1));
parts.push(ENTRY.date + '_day=' + d.getDate());

const fields = [
  ['shift',             parsed.shift],
  ['group',             parsed.group],
  ['sku',               parsed.sku || ''],
  ['machine',           parsed.machine],
  ['plan_box',          parsed.plan_box],
  ['actual_box',        parsed.actual_box],
  ['workers',           parsed.workers ?? 0],
  ['actual_pcs',        parsed.actual_pcs],
  ['run_time',          parsed.run_time],
  ['counter',           parsed.counter ?? 0],
  ['machine_cycle',     parsed.machine_cycle ?? 0],
  ['setup_time',        parsed.setup_time],
  ['break_time',        parsed.break_time],
  ['clean_time',        parsed.clean_time],
  ['stop_after_target', parsed.stop_after_target ?? 30],
  ['bdown_time',        parsed.bdown_time ?? 0],
  ['machine_run_time',  parsed.machine_run_time],
  ['status',            parsed.status],
  ['miss_reason',       parsed.miss_reason || '-'],
  ['warehouse_pcs',     parsed.warehouse_pcs],
  ['waste_pcs',         parsed.waste_pcs ?? 0],
  ['damage_reason',     parsed.damage_reason || '']
];

for (const [key, val] of fields) {
  if (val !== undefined && val !== null) {
    parts.push(ENTRY[key] + '=' + encodeURIComponent(String(val)));
  }
}

// waste_type: ส่งเฉพาะตอนมีค่า (checkbox จะไม่ส่งถ้าไม่ได้เลือก)
if (parsed.waste_type) {
  parts.push(ENTRY.waste_type + '=' + encodeURIComponent(parsed.waste_type));
}
parts.push(ENTRY.waste_type + '_sentinel=');
parts.push('submit=Submit');

return [{
  json: {
    formBody: parts.join('&'),
    parsed,
    chatId: $('Telegram Trigger').first().json.message.chat.id
  }
}];

