=รายงานของคุณถูกบันทึกแล้ว
รหัสรายงาน: {{ $('Append row in sheet').first().json.report_id }}
กรุณารอการอนุมัติจากผู้ตรวจสอบ

parameters.jsCode:
const parsed = $input.first().json?.message?.content
            || $input.first().json?.content
            || $input.first().json;

const lines = parsed.lines || [];
const date = parsed.date || new Date().toISOString().split('T')[0];
const shift = parsed.shift || '';

return lines.map(line => ({
  json: {
    วันที่: date,
    กะ: shift,
    กลุ่ม: line.group || '',
    สินค้า: line.product || '',
    เครื่อง: line.machine || '',
    แผน: line.plan || 0,
    คน: line.workers || 0,
    chatId: $('Telegram Trigger').first().json.message.chat.id
  }
}));

const production = $('Build Form Body').first().json.parsed;
const planRows = $input.all().map(item => item.json);

// ค้นหาแผนที่ตรงกับสินค้า/เครื่อง
const productKey = (production.sku || production.machine || '').toLowerCase();

const planRow = planRows.find(row => {
  const planProduct = (row['สินค้า'] || '').toLowerCase();
  const planMachine = (row['เครื่อง'] || '').toLowerCase();
  return planProduct.includes(productKey) || 
         productKey.includes(planProduct) ||
         (planMachine && productKey.includes(planMachine));
});

// Merge ข้อมูลแผนเข้ากับยอดผลิต
const merged = { ...production };
if (planRow) {
  if (!merged.plan_box || merged.plan_box === 0) merged.plan_box = planRow['แผน'] || 0;
  if (!merged.workers || merged.workers === 0) merged.workers = planRow['คน'] || 0;
  if (!merged.machine || merged.machine === '') merged.machine = planRow['เครื่อง'] || '';
  if (!merged.shift || merged.shift === '') merged.shift = planRow['กะ'] || '';
  if (!merged.date || merged.date === '') merged.date = planRow['วันที่'] || '';
}

return [{
  json: {
    parsed: merged,
    chatId: $('Telegram Trigger').first().json.message.chat.id
  }
}];

const text = $json.message.text || '';
const telegramId = String($json.message.from.id);
const chatId = $json.message.chat.id;

// ดึงชื่อออกจาก "/register จักรกฤษ"
const nameQuery = text.replace('/register', '').trim();

if (!nameQuery) {
  return [{ json: { 
    found: false, 
    chatId, 
    replyText: '❌ กรุณาส่งชื่อด้วย\n\nตัวอย่าง:\n/register จักรกฤษ'
  }}];
}

return [{ json: { telegramId, chatId, nameQuery, found: null } }];

const { telegramId, chatId, nameQuery } = $('Parse Register').first().json;
const members = $input.all().map(i => i.json);

// ค้นหาชื่อที่ตรงกัน
const match = members.find(m => {
  const fullName = (m['ชื่อ'] || '').toLowerCase();
  const firstName = fullName.split(' ')[0];
  const query = nameQuery.toLowerCase();
  return fullName.includes(query) || query.includes(firstName);
});

if (!match) {
  return [{ json: {
    found: false,
    chatId,
    replyText: `❌ ไม่พบชื่อ "${nameQuery}" ในระบบ\n\nลองใหม่อีกครั้ง เช่น:\n/register จักรกฤษ`
  }}];
}

return [{ json: {
  found: true,
  chatId,
  telegramId,
  memberName: match['ชื่อ'],
  memberShift: match['กะ'],
  rowNumber: match['row_number'],
  replyText: `✅ ลงทะเบียนสำเร็จ!\nชื่อ: ${match['ชื่อ']}\nกะ: ${match['กะ']}`
}}];

const production = $('Merge with Plan').first().json.parsed;
const chatId = $('Merge with Plan').first().json.chatId;
const members = $input.all().map(i => i.json);

// สร้าง Report ID ตรงนี้เลย
const reportId = 'RPT-' + Date.now();

const member = members.length > 0 ? members[0] : null;

if (!member) {
  return [{ json: {
    notRegistered: true,
    chatId,
    replyText: '❌ คุณยังไม่ได้ลงทะเบียน\nกรุณาส่ง /register ชื่อ-นามสกุล\nเช่น /register จักรกฤษ พูลสวัสดิ์'
  }}];
}

const enriched = {
  ...production,
  ชื่อ: member['ชื่อ'],
  กะ: production.shift || member['กะ'],
  role: member['role'] || 'พนักงาน'
};

return [{ json: {
  notRegistered: false,
  parsed: enriched,
  chatId,
  report_id: reportId,
  role: member['role'] || 'พนักงาน'
}}];

const senderData = $('Add Sender Info').first().json;
const parsed = senderData.parsed;
const skuKeyword = (parsed.sku || '').toLowerCase().trim();

const skuRows = $input.all().map(i => i.json);

let match = skuRows.find(r =>
  r.keyword && r.keyword.toLowerCase().trim() === skuKeyword
);

if (!match) {
  match = skuRows.find(r =>
    r.keyword && (
      skuKeyword.includes(r.keyword.toLowerCase().trim()) ||
      r.keyword.toLowerCase().trim().includes(skuKeyword)
    )
  );
}

let skuCode = '';
let productName = '';
let group = parsed.group || '';

if (match) {
  const fullProduct = match.full_product || '';
  const parts = fullProduct.split(' ');
  skuCode = parts[0];
  productName = parts.slice(1).join(' ').replace(/\*/g, '×');
  group = match.group || parsed.group || '';
} else {
  productName = (parsed.sku || '').replace(/\*/g, '×');
  group = parsed.group || '';
}

return [{
  json: {
    ...senderData,
    parsed: {
      ...parsed,
      sku_code: skuCode,
      product_name: productName,
      group: group
    }
  }
}];

