const data = $('Resolve SKU').first().json;
const chatId = data.chatId;
const parsed = data.parsed;

const timestamp = Date.now();
const reportId = 'RPT-' + timestamp;

return [{
  json: {
    report_id: reportId,
    chatId: chatId,
    parsed: parsed
  }
}];

const trigger = $('Telegram Trigger').first().json;
const callbackQuery = trigger.callback_query;
const message = trigger.message;

let text, chatId;

if (callbackQuery) {
  text = callbackQuery.data || '';
  chatId = callbackQuery.message.chat.id;
} else {
  text = (message && message.text) || '';
  chatId = message && message.chat.id;
}

const parts = text.trim().split(/\s+/);
const rawCommand = parts[0].toLowerCase();
const command = rawCommand.split('@')[0];
const reportId = parts[1] || '';
const action = command.includes('approve') ? 'approve' : 'reject';

if (!reportId || !reportId.startsWith('RPT-')) {
  return [{ json: {
    error: true,
    chatId,
    replyText: '❌ รูปแบบไม่ถูกต้อง\nใช้: /approve RPT-xxxxx หรือ /reject RPT-xxxxx'
  }}];
}

return [{ json: {
  error: false,
  action,
  reportId,
  chatId
}}];

const action = $('Parse Approve/Rejectpt').first().json.action;
const reportId = $('Parse Approve/Rejectpt').first().json.reportId;
const reviewerChatId = $('Parse Approve/Rejectpt').first().json.chatId;

const rows = $input.all().map(i => i.json);
const match = rows.find(r => r['report_id'] === reportId);

if (!match) {
  return [{ json: {
    found: false,
    action,
    reportId,
    reviewerChatId,
    replyText: `ไม่พบรายงาน ${reportId}\nอาจถูกอนุมัติหรือปฏิเสธไปแล้ว`
  }}];
}

return [{ json: {
  found: true,
  action,
  reportId,
  reviewerChatId,
  workerChatId: match['chatId'],
 rowNumber: match['row_number'],
  rowData: match
}}];

const senderData = $('Normalize Web Report').first().json;
const parsed = senderData.parsed;
const skuKeyword = (parsed.sku || '').toLowerCase().trim();

const skuRows = $input.all().map(i => i.json);

let match = skuRows.find(r =>
  r.keyword && r.keyword.toLowerCase().trim() === skuKeyword
);

if (!match) {
  match = skuRows.find(r =>
    r.keyword && (
      skuKeyword.includes(r.keyword.toLowerCase().trim()) ||
      r.keyword.toLowerCase().trim().includes(skuKeyword)
    )
  );
}

let skuCode = '';
let productName = '';
let group = parsed.group || '';

if (match) {
  const fullProduct = match.full_product || '';
  const parts = fullProduct.split(' ');
  skuCode = parts[0];
  productName = parts.slice(1).join(' ').replace(/\*/g, '×');
  group = match.group || parsed.group || '';
} else {
  productName = (parsed.sku || '').replace(/\*/g, '×');
  group = parsed.group || '';
}

return [{
  json: {
    ...senderData,
    parsed: {
      ...parsed,
      sku_code: skuCode,
      product_name: productName,
      group: group
    }
  }
}];

